std::mutex m; std::condition_variable cv; std::deque<Job> q;
void push(Job j) { { std::lock_guard<std::mutex> lk(m); q.push_back(std::move(j)); }
                   cv.notify_one(); }          // exactly one waiter proceeds
Job pop() { std::unique_lock<std::mutex> lk(m);
            cv.wait(lk, [&]{ return !q.empty(); });
            Job j = std::move(q.front()); q.pop_front(); return j; }

